package com.gamehub;
import com.gamehub.application.*; import com.gamehub.infrastructure.*; import org.junit.jupiter.api.Test; import java.nio.file.*; import java.time.*; import static org.junit.jupiter.api.Assertions.*;
class PaymentSliceTest { @Test void completedSessionCanBeSettledOnceAndRejectsUnderpayment() throws Exception {Path p=Files.createTempFile("payment-", ".db");try(Database db=new Database(p)){var us=new UserService(db);us.bootstrap("m","password1");var u=us.authenticate("m","password1");var o=new OperationsService(db);long station=o.addStation("P-01","PC",50000);long res=o.reserve(u.id(),station,Instant.now().plusSeconds(3600),Instant.now().plusSeconds(7200));long session=o.startSession(res);o.finishSession(session,12000);assertThrows(IllegalArgumentException.class,()->o.settleSession(u.id(),session,10000,"CASH","r-1"));long payment=o.settleSession(u.id(),session,12000,"CASH","r-1");assertTrue(payment>0);assertThrows(IllegalStateException.class,()->o.settleSession(u.id(),session,12000,"CASH","r-1"));}finally{Files.deleteIfExists(p);}}}
